"use strict";
const fs = require("node:fs");
const path = require("node:path");
const cp = require("node:child_process");
const crypto = require("node:crypto");
const root = __dirname;
const previous = "/tmp/cew-pr62-optimized-20261018-4Wo7oE";
const probes = JSON.parse(fs.readFileSync(path.join(previous, "cost-probes.json")));
const rows = [1, 2].map((run) => {
  const trial = path.join(previous, "trials", `more-itertools-1247--gpt-fixed--r${run}`);
  const source = fs.readFileSync(path.join(trial, "runs/more-itertools-1247", `gpt-fixed-r${run}`, "more_itertools/more.py"), "utf8");
  const rawLog = fs.readFileSync(path.join(trial, "results/more-itertools-1247", `gpt-fixed-r${run}`, "agent.log"), "utf8");
  const events = rawLog.split("\n").flatMap((line) => { try { return [JSON.parse(line)]; } catch { return []; } });
  const commands = events.filter((e) => e.type === "item.completed" && e.item?.type === "command_execution")
    .map((e) => ({ command: e.item.command, exit_code: e.item.exit_code }));
  const cases = ["large_length", "first_repeated_index"].map((operation) => {
    const start = Date.now();
    const result = cp.spawnSync(path.join(previous, "venvs/more-itertools/bin/python"), ["-B", "-c", probes.python_program], {
      input: JSON.stringify({ source, operation, support: path.join(previous, "validation/more-itertools-1247/checkout") }),
      encoding: "utf8", timeout: 2000, env: { ...process.env, PYTHONDONTWRITEBYTECODE: "1" }
    });
    let value;
    try { value = JSON.parse(result.stdout); } catch { value = { passed: false, stderr: result.stderr?.slice(-800) }; }
    return { operation, ...value, passed: result.status === 0 && value.passed === true,
      timed_out: result.error?.code === "ETIMEDOUT", duration_ms: Date.now() - start, exit: result.status };
  });
  return { run, source_sha256: crypto.createHash("sha256").update(source).digest("hex"), cases,
    loaded_testing_rule: commands.some((c) => c.command.includes("common/testing.md")),
    loaded_review_skill: commands.some((c) => c.command.includes("skills/code-review/SKILL.md")), commands };
});
fs.writeFileSync(path.join(root, "diagnosis.json"), JSON.stringify({ measured_source: "6238192c244f7c719934c266ef8e3991a397ae78",
  hypothesis: "The rule was loaded, but selecting representative types did not require a separate sequence oracle or a correction-loop work bound. Normal samples did not exercise repeated rounded values or large correction distances.",
  alternative_explanation_checked: "Both failing and passing artifacts loaded testing.md and the review skill; original supplied tests and previously frozen boundary queries passed for the failing artifact. This is not an omitted rule load or an original-suite failure.",
  python_program: probes.python_program, controller_source: fs.readFileSync(__filename, "utf8"), rows }, null, 2) + "\n");
console.log(JSON.stringify(rows.map(({ run, cases, loaded_testing_rule, loaded_review_skill }) => ({ run, cases, loaded_testing_rule, loaded_review_skill })), null, 2));

